        underlyingBalance(),
        outstandingAmount,
        totalSupply
    );
}

function underlyingBalance() public view returns (uint256) {
    uint256 _pool = IERC20(underlyingToken).balanceOf(address(this));
    return _pool.add(outstandingAmount);
}

